from __future__ import annotations

"""Deterministic auto-layout only — no knowledge of manual host drags."""

from collections.abc import Sequence

from breakout_state import BreakoutLayoutError, BreakoutSessionState


def _require_non_empty_people(participant_ids: Sequence[str]) -> list[str]:
    if not participant_ids:
        raise BreakoutLayoutError("participants required for auto layout")
    return [str(p).strip() for p in participant_ids]


def _require_rooms(room_ids: Sequence[str]) -> list[str]:
    if not room_ids:
        raise BreakoutLayoutError("room_ids required for auto layout")
    return [str(r).strip() for r in room_ids]


def build_balanced_assignments(room_ids: Sequence[str], participant_ids: Sequence[str]) -> dict[str, str]:
    rooms = _require_rooms(room_ids)
    people = _require_non_empty_people(participant_ids)
    for p in people:
        if not p:
            raise BreakoutLayoutError("participant_id cannot be blank")
    if len(set(people)) != len(people):
        raise BreakoutLayoutError("duplicate participant_id")
    if len(set(rooms)) != len(rooms):
        raise BreakoutLayoutError("duplicate room_id")

    ordered_rooms = list(rooms)
    ordered_people = sorted(people)
    out: dict[str, str] = {}
    for idx, pid in enumerate(ordered_people):
        room = ordered_rooms[idx % len(ordered_rooms)]
        out[pid] = room
    return out


def auto_map_for_session(state: BreakoutSessionState) -> dict[str, str]:
    return build_balanced_assignments(state.room_ids, state.participant_ids)


def preview_room_load(auto_map: dict[str, str], room_ids: Sequence[str]) -> dict[str, int]:
    loads: dict[str, int] = {r: 0 for r in room_ids}
    for rid in auto_map.values():
        loads[rid] = loads.get(rid, 0) + 1
    return loads


def max_room_spread(loads: dict[str, int]) -> int:
    if not loads:
        return 0
    values = list(loads.values())
    return max(values) - min(values)


def explain_auto_choice(participant_id: str, room_id: str, slot: int) -> str:
    return f"auto {participant_id} -> {room_id} (slot {slot})"


def partition_new_vs_returning(
    participant_ids: Sequence[str],
    already_assigned: set[str],
) -> tuple[list[str], list[str]]:
    new_list: list[str] = []
    returning: list[str] = []
    for pid in sorted(participant_ids):
        token = str(pid).strip()
        if token in already_assigned:
            returning.append(token)
        else:
            new_list.append(token)
    return new_list, returning


def merge_missing_only(
    base: dict[str, str],
    extra: dict[str, str],
) -> dict[str, str]:
    merged = dict(base)
    for pid, rid in extra.items():
        merged.setdefault(pid, rid)
    return merged


def strip_unknown_targets(auto_map: dict[str, str], valid_participants: set[str]) -> dict[str, str]:
    return {pid: rid for pid, rid in auto_map.items() if pid in valid_participants}


def auto_layout_signature(room_ids: Sequence[str], participant_ids: Sequence[str]) -> str:
    r = "|".join(sorted(str(x).strip() for x in room_ids))
    p = "|".join(sorted(str(x).strip() for x in participant_ids))
    return f"{r}::{p}"


def sorted_assignment_items(auto_map: dict[str, str]) -> list[tuple[str, str]]:
    return sorted(auto_map.items(), key=lambda pair: pair[0])


def is_balance_acceptable(auto_map: dict[str, str], room_ids: Sequence[str], max_skew: int = 1) -> bool:
    loads = preview_room_load(auto_map, room_ids)
    return max_room_spread(loads) <= max_skew


def invert_map(room_by_participant: dict[str, str]) -> dict[str, list[str]]:
    inv: dict[str, list[str]] = {}
    for pid, rid in sorted(room_by_participant.items()):
        inv.setdefault(rid, []).append(pid)
    for rid in inv:
        inv[rid].sort()
    return inv


def diff_maps(before: dict[str, str], after: dict[str, str]) -> list[str]:
    changed: list[str] = []
    keys = sorted(set(before) | set(after))
    for pid in keys:
        if before.get(pid) != after.get(pid):
            changed.append(pid)
    return changed

