from __future__ import annotations

"""Read-only reporting for support — depends only on session state."""

from breakout_state import BreakoutSessionState


def summarize_breakout_layout(state: BreakoutSessionState) -> dict[str, object]:
    room_to_people: dict[str, list[str]] = {}
    for pid in state.participant_ids:
        rid = state.room_by_participant.get(pid)
        if rid is None:
            continue
        room_to_people.setdefault(rid, []).append(pid)
    for rid in room_to_people:
        room_to_people[rid].sort()

    missing = state.participants_missing_room()
    loads = {rid: len(room_to_people.get(rid, [])) for rid in state.room_ids}

    return {
        "meeting_id": state.meeting_id,
        "room_count": len(state.room_ids),
        "participant_count": len(state.participant_ids),
        "occupants_by_room": {rid: list(room_to_people.get(rid, [])) for rid in state.room_ids},
        "room_loads": loads,
        "manual_pin_count": len(state.manual_pins),
        "manual_pins": sorted(state.manual_pins),
        "missing_room": missing,
    }


def layout_health_flag(summary: dict[str, object]) -> str:
    if summary["missing_room"]:
        return "incomplete"
    loads = summary["room_loads"]
    if not loads:
        return "idle"
    values = list(loads.values())
    if max(values) - min(values) > 1:
        return "skewed"
    return "ok"


def format_support_ticket(summary: dict[str, object]) -> str:
    mid = summary["meeting_id"]
    pins = summary["manual_pin_count"]
    missing = len(summary["missing_room"])
    return f"[{mid}] pins={pins} unassigned={missing}"


def roster_room_pairs(state: BreakoutSessionState) -> list[tuple[str, str]]:
    pairs: list[tuple[str, str]] = []
    for pid in state.participant_ids:
        rid = state.room_by_participant.get(pid)
        if rid is not None:
            pairs.append((pid, rid))
    return sorted(pairs)


def participant_room_line(participant_id: str, room_id: str | None) -> str:
    if room_id is None:
        return f"{participant_id}:<none>"
    return f"{participant_id}:{room_id}"


def audit_short_hash(summary: dict[str, object]) -> str:
    return f"{summary['participant_count']}p-{summary['room_count']}r-{summary['manual_pin_count']}m"


def explain_missing_missing(summary: dict[str, object]) -> str:
    missing = summary["missing_room"]
    if not missing:
        return "all assigned"
    return "missing:" + ",".join(missing)


def flatten_occupants(summary: dict[str, object]) -> list[str]:
    lines: list[str] = []
    occ = summary["occupants_by_room"]
    for rid in sorted(occ.keys()):
        for pid in occ[rid]:
            lines.append(f"{pid}@{rid}")
    return sorted(lines)


def compare_audits(before: dict[str, object], after: dict[str, object]) -> bool:
    return before.get("occupants_by_room") == after.get("occupants_by_room")

