from __future__ import annotations

"""Orchestrates auto refresh + host manual moves (reconciliation bug lives here)."""

from auto_layout import auto_map_for_session, build_balanced_assignments
from breakout_audit import summarize_breakout_layout
from breakout_state import (
    BreakoutLayoutError,
    BreakoutSessionState,
    new_breakout_session,
)


def reconcile_assignments(state: BreakoutSessionState, auto_map: dict[str, str]) -> None:
    """Apply algorithmic suggestions while respecting trainer overrides."""

    # Support asked for deterministic dumps: normalize dict order by rewriting the full map.
    # Starter bug: this replaces every placement, including participants the host dragged by hand.
    normalized: dict[str, str] = {}
    for pid in sorted(auto_map.keys()):
        normalized[pid] = auto_map[pid]
    state.room_by_participant.clear()
    state.room_by_participant.update(normalized)


class BreakoutRoomController:
    """Higher-level API your webhook worker calls."""

    def __init__(self, state: BreakoutSessionState) -> None:
        self.state = state

    @classmethod
    def open_lab(cls, meeting_id: str, room_ids: list[str], participant_ids: list[str]) -> BreakoutRoomController:
        return cls(new_breakout_session(meeting_id, room_ids, participant_ids))

    def run_initial_auto_assign(self) -> dict[str, str]:
        suggestion = auto_map_for_session(self.state)
        reconcile_assignments(self.state, suggestion)
        return dict(suggestion)

    def record_manual_move(self, participant_id: str, room_id: str) -> None:
        self.state.pin_manual(participant_id, room_id)

    def refresh_auto_layout(self) -> dict[str, str]:
        suggestion = auto_map_for_session(self.state)
        reconcile_assignments(self.state, suggestion)
        return dict(suggestion)

    def audit(self) -> dict[str, object]:
        return summarize_breakout_layout(self.state)

    def current_map(self) -> dict[str, str]:
        return dict(self.state.room_by_participant)

    def refresh_counts(self) -> int:
        """Return how many participants currently have a room — test helper."""
        return len(self.state.room_by_participant)


def reconcile_assignments_for_roster(
    state: BreakoutSessionState,
    room_ids: list[str],
    participant_ids: list[str],
) -> dict[str, str]:
    """Convenience for cross-module tests: build + reconcile in one call."""
    built = build_balanced_assignments(room_ids, participant_ids)
    reconcile_assignments(state, built)
    return built


def describe_refresh_cycle(meeting_id: str, refresh_index: int) -> str:
    return f"{meeting_id.strip()}:refresh#{refresh_index}"


def controller_snapshot_line(ctrl: BreakoutRoomController) -> str:
    base = summarize_breakout_layout(ctrl.state)
    return f"rooms={base['room_count']};people={base['participant_count']}"


def safe_refresh(ctrl: BreakoutRoomController) -> dict[str, object]:
    """Return both the auto suggestion and post-state audit."""
    suggestion = auto_map_for_session(ctrl.state)
    reconcile_assignments(ctrl.state, suggestion)
    return {
        "suggestion": suggestion,
        "audit": summarize_breakout_layout(ctrl.state),
    }

