    for pid in participant_ids:
        token = pid.strip()
        if not token:
            raise BreakoutLayoutError("participant_id cannot be blank")
        if token in seen:
            raise BreakoutLayoutError("duplicate participant_id")
        seen.add(token)
        out.append(token)
    return out


def _normalize_room_ids(room_ids: list[str]) -> tuple[str, ...]:
    if not room_ids:
        raise BreakoutLayoutError("room_ids required")
    cleaned: list[str] = []
    seen: set[str] = set()
    for rid in room_ids:
        token = rid.strip()
        if not token:
            raise BreakoutLayoutError("room_id cannot be blank")
        if token in seen:
            raise BreakoutLayoutError("duplicate room_id")
        seen.add(token)
        cleaned.append(token)
    return tuple(cleaned)


@dataclass
class BreakoutSessionState:
    """Mutable placement state the controller updates."""

    meeting_id: str
    room_ids: tuple[str, ...]
    participant_ids: tuple[str, ...]
    room_by_participant: dict[str, str] = field(default_factory=dict)
    manual_pins: set[str] = field(default_factory=set)

    def __post_init__(self) -> None:
        mid = self.meeting_id.strip()
        if not mid:
            raise BreakoutLayoutError("meeting_id required")
        self.meeting_id = mid
        if len(self.participant_ids) == 0:
            raise BreakoutLayoutError("participants required")

    def participant_set(self) -> set[str]:
        return set(self.participant_ids)

    def ensure_participant(self, participant_id: str) -> str:
        token = participant_id.strip()
        if token not in self.participant_set():
            raise BreakoutLayoutError("unknown participant_id")
        return token

    def ensure_room(self, room_id: str) -> str:
        token = room_id.strip()
        if token not in self.room_ids:
            raise BreakoutLayoutError("unknown room_id")
        return token

    def pin_manual(self, participant_id: str, room_id: str) -> None:
        pid = self.ensure_participant(participant_id)
        rid = self.ensure_room(room_id)
        self.room_by_participant[pid] = rid
        self.manual_pins.add(pid)

    def clear_layout_memory(self) -> None:
        """Test helper: wipe placements without touching roster metadata."""
        self.room_by_participant.clear()
        self.manual_pins.clear()

    def pinned_count(self) -> int:
        return len(self.manual_pins)

    def participants_missing_room(self) -> list[str]:
        return [pid for pid in self.participant_ids if pid not in self.room_by_participant]


def new_breakout_session(meeting_id: str, room_ids: list[str], participant_ids: list[str]) -> BreakoutSessionState:
    rooms = _normalize_room_ids(room_ids)
    people = tuple(_dedupe_preserve_order(list(participant_ids)))
    return BreakoutSessionState(
        meeting_id=meeting_id,
        room_ids=rooms,
        participant_ids=people,
    )


def session_fingerprint(state: BreakoutSessionState) -> str:
    return f"{state.meeting_id}:{len(state.room_ids)}:{len(state.participant_ids)}:{state.pinned_count()}"


def clone_placement(state: BreakoutSessionState) -> dict[str, str]:
    return dict(state.room_by_participant)


def pins_frozenset(state: BreakoutSessionState) -> frozenset[str]:
    return frozenset(state.manual_pins)


def format_room_label(room_id: str, index: int) -> str:
    return f"{room_id}#{index}"


def describe_pinning(participant_id: str, room_id: str) -> str:
    return f"pin {participant_id.strip()} -> {room_id.strip()}"
